def deserialize(self, content):
    try:
        content = content.decode("utf-8")
    except AttributeError:
        pass
    try:
        body = json.loads(content)
    except json.decoder.JSONDecodeError:
        body = content
    else:
        if self._data_wrapper and "data" in body:
            body = body["data"]
    return body

